115 |     /// @notice Claims licenses for team members and make sure they do not exceed their personal claim cap.
116 |     /// @param amount The amount of licenses to claim
117 |     /// @param data Index and claimCap in encoded format
118 |     /// @param merkleProof The proof used to verify whether the caller is allowed to claim the licenses
119 |     function claimLicenseTeam(uint256 amount, bytes calldata data, bytes32[] calldata merkleProof) public {
120 |         if(!teamSaleActive) revert TeamSaleNotActive();
121 |         (uint256 index, uint256 claimCap) = abi.decode(data,(uint256,uint256));
122 |         uint256 claimedLicenses = teamClaimsPerAddress[msg.sender];
123 |         if(amount + claimedLicenses > claimCap) revert IndividualClaimCapExceeded();
124 |         bytes32 node = keccak256(abi.encodePacked(index, msg.sender, claimCap));
125 |         if (!MerkleProof.verify(merkleProof, teamMerkleRoot, node)) revert InvalidProof();
126 |         teamClaimsPerAddress[msg.sender] += amount;
127 |         totalLicenses += amount;
128 |         emit TeamLicensesClaimed(msg.sender, amount);
129 |     }
