136 |     function claimLicenseFriendsFamily(uint256 amount, bytes calldata data, bytes32[] calldata merkleProof) public payable {
137 |         if(!friendsFamilySaleActive) revert FriendsFamilySaleNotActive();
138 |         (uint256 index, uint256 claimCap) = abi.decode(data,(uint256,uint256));
139 |         uint256 claimedLicenses = friendsFamilyClaimsPerAddress[msg.sender];
140 |         if(amount + claimedLicenses > claimCap) revert IndividualClaimCapExceeded();
141 |         bytes32 node = keccak256(abi.encodePacked(index, msg.sender, claimCap));
142 |         if (!MerkleProof.verify(merkleProof, friendsFamilyMerkleRoot, node)) revert InvalidProof();
143 |         uint256 toPay = tiers[1].price * amount;
144 |         if(msg.value < toPay) revert InsufficientPayment();
145 |         friendsFamilyClaimsPerAddress[msg.sender] += amount;
146 |         totalLicenses += amount;
147 |         emit FriendsFamilyLicensesClaimed(msg.sender, toPay, amount);
148 |     }
